<?php
namespace App\Http\Controllers;
use App\Models\{EventFaceIndexRun,FaceSearchSubject,Group,MediaAsset};use Illuminate\Http\Request;use Illuminate\Support\Facades\Gate;use Inertia\Inertia;
class LensPicUiController extends Controller{public function dashboard(Request$r){$owned=$r->user()->createdGroups()->withCount(['photos','members'])->latest()->limit(6)->get();return Inertia::render('Dashboard',['stats'=>['events'=>$r->user()->createdGroups()->count(),'photos'=>$r->user()->photos()->count(),'participants'=>$owned->sum('members_count'),'processing'=>MediaAsset::whereIn('group_id',$owned->pluck('id'))->whereIn('state',['queued','processing'])->count()],'events'=>$owned,'recent'=>[]]);}public function events(Request$r){$events=$r->user()->createdGroups()->withCount(['photos','members'])->latest()->get()->merge($r->user()->groups()->withCount(['photos','members'])->latest()->get())->unique('id')->values();return Inertia::render('Events/Index',['events'=>$events]);}public function create(Request$r){abort_unless($r->user()->account_type==='photographer'||$r->user()->isAdmin(),403);return Inertia::render('Events/Create');}public function show(Request$r,Group$group){Gate::authorize('view',$group);$admin=$group->isAdmin($r->user());if($admin)foreach([\App\Models\GroupAccessInvite::PARTIAL,\App\Models\GroupAccessInvite::FULL]as$type)\App\Models\GroupAccessInvite::firstOrCreate(['group_id'=>$group->id,'access_type'=>$type],['access_code'=>\App\Models\GroupAccessInvite::generateCode(),'invitation_token'=>\Illuminate\Support\Str::random(48),'created_by'=>$r->user()->id]);$photos=$group->photos()->with('mediaAsset')->latest()->limit(60)->get()->filter(fn($p)=>Gate::forUser($r->user())->allows('view',$p))->map(fn($p)=>['id'=>$p->id,'original_filename'=>$p->original_filename,'url'=>$p->mediaAsset?route('media.show',[$p->mediaAsset->uuid,'thumbnail']):$p->thumbnail_url])->values();return Inertia::render('Events/Show',['event'=>$group,'photos'=>$photos,'members'=>$admin?$group->members()->limit(20)->get(['users.id','name']):[],'invites'=>$admin?$group->accessInvites()->get()->map(fn($i)=>['id'=>$i->id,'label'=>$i->label,'access_code'=>$i->access_code]):[],'indexRun'=>$admin?EventFaceIndexRun::where('group_id',$group->id)->latest()->first():null]);}}
